  "atomic_questions": [
    "What is the objective of this analysis — are we maximizing the total value of exports (i.e., the value of domestically produced goods sold on the world market), or is there a different goal such as minimizing imports or maximizing net trade balance?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

